mapper.select:
select exists(select 1 from article_contributor
              where article_id = #{articleId} and user_id = #{userId}
                and status = 'APPROVED' and deleted = 0)

select c.contributor_id, c.article_id, c.user_id, c.status, c.advice, c.apply_by, c.apply_time, c.handle_by, c.handle_time, c.create_by, c.create_time, c.update_by, c.update_time, c.deleted, a.title as article_title, au.nick_name as nick_name, auu.nick_name as article_nick_name from article_contributor c inner join article a on c.article_id = a.article_id and a.deleted = 0 left join sys_user au on c.user_id = au.user_id left join sys_user auu on a.author_id = auu.user_id where c.deleted = 0 and a.author_id = #{articleAuthorId}
and c.status = #{status}
order by c.apply_time desc, c.contributor_id desc

select c.contributor_id, c.article_id, c.user_id, c.status, c.advice, c.apply_by, c.apply_time, c.handle_by, c.handle_time, c.create_by, c.create_time, c.update_by, c.update_time, c.deleted, a.title as article_title, au.nick_name as nick_name, auu.nick_name as article_nick_name from article_contributor c inner join article a on c.article_id = a.article_id and a.deleted = 0 left join sys_user au on c.user_id = au.user_id left join sys_user auu on a.author_id = auu.user_id where c.deleted = 0 and c.user_id = #{userId}
and c.status = #{status}
order by c.apply_time desc, c.contributor_id desc

mapper.update:
update article_contributor set status = #{status}, handle_by = #{handleBy}, handle_time = #{handleTime}, update_by = #{updateBy}
, advice = #{advice}
where contributor_id = #{contributorId} and deleted = 0
